
/* =========================================================================
   design-core.js — design raster core: state sync, design canvas cache,
   registration-mark data, toast, artwork draw + texture rebuild, flat compose.
   Load: FIRST app slice (after export.js). No DOM widget wiring here.
   ========================================================================= */
/* UI bindings overview (S4): state/config/drafts in store.js; pipeline in export.js */
function syncActive(){ state.img = activeLayer(); }
/* raster cache for INACTIVE designs (page preview); the active design always
   uses the live `tex` canvas, rebuilt by rebuildTexture() */
const _dcache = new Map();
function clearDesignCache(){ _dcache.clear(); }
function designCanvas(i){
  if(!(i >= 0) || i >= state.designs.length) i = 0;
  if(i === state.activeDesign) return tex;
  const d = state.designs[i];
  const hit = _dcache.get(i);
  if(hit && hit.ver === d.ver && hit.wrapW === state.wrap.w && hit.wrapH === state.wrap.h
     && hit.notch === state.notch && hit.bg === state.bg) return hit.c;
  const c = document.createElement('canvas');
  const W = 1400, H = Math.round(W * state.wrap.h / state.wrap.w);
  c.width = W; c.height = H;
  drawArtwork(c.getContext('2d'), W, H, W/state.wrap.w, false, i);
  _dcache.set(i, {ver:d.ver, c, wrapW:state.wrap.w, wrapH:state.wrap.h,
                  notch:state.notch, bg:state.bg});
  return c;
}

/* ---- registration-mark glyphs extracted from official manuals, embedded as
   base64 JPEG (sub-layer in the PDF). Sources:
   MARK_SIL_*  = Silhouette Connect manual p.9, Type 1 figure (600→2400dpi crops)
   MARK_BRO    = Brother ScanNCut Link manual, Registration-mark diagram (2400dpi) ---- */
const MARK_DATA = {};
MARK_DATA["SIL_SQ"]="data:image/jpeg;base64,";
MARK_DATA["SIL_L_TR"]="data:image/jpeg;base64,";
MARK_DATA["SIL_L_BL"]="data:image/jpeg;base64,";
MARK_DATA["BRO"]="data:image/jpeg;base64,";


const MARK_IMGS = {};   /* populated at boot (js/app.js) — instantiating here would race
                           later-loaded scripts: a data-URL image can fire onload before
                           drawPagePrev() is declared, silently killing the refresh */
function esc(s){ return String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function dataUrlBytes(u){
  const b = atob(u.slice(u.indexOf(',')+1));
  const a = new Uint8Array(b.length);
  for(let i=0;i<b.length;i++) a[i] = b.charCodeAt(i);
  return a;
}

/* alpha = source transparency ONLY (개정 2026-10-05).
   White keying removed: pixels carrying CMYK(0,0,0,0) are valid data and stay opaque;
   only source pixels with no data (transparent) render as alpha. */
function layerSrc(im){ return (im && im.bmp) ? im.bmp : im; }

/* ---------- toast ---------- */
let toastT=0;
function toast(msg, kind, code){
  const t=$('#toast'); t.textContent=msg; t.className='show'+(kind?' '+kind:'');
  t.dataset.code = code || '';                 // machine code for tests (copy may change freely)
  clearTimeout(toastT); toastT=setTimeout(()=>{t.className='';},3200);
}

/* ---------- wrap texture (flat artwork) ---------- */
/* 운영 설정은 js/config.js (관리 페이지가 수정하는 파일)에서 관리합니다. */
const AD = CFG.ad || MT_CFG_DEFAULT.ad;
const tex = document.createElement('canvas');
function drawArtwork(ctx, W, H, ppm, mirror, designIdx, env){
  const E = env || state;                          // S3a: pass a draft env for state-free rendering
  ctx.save();
  if(mirror){ ctx.translate(W,0); ctx.scale(-1,1); }
  ctx.fillStyle = E.bg;
  ctx.fillRect(0,0,W,H);
  const di = (designIdx===undefined || designIdx===null) ? E.activeDesign : designIdx;
  const dsn = E.designs[di];
  if(dsn){
    for(const im of dsn.layers){          // bottom -> top (stack order)
      if(!im.visible) continue;
      const aspect = im.bmp.height/im.bmp.width;
      const wPx = im.w*ppm, hPx = im.w*aspect*ppm;
      ctx.save();
      ctx.translate(im.cx*ppm, im.cy*ppm);
      ctx.rotate(im.rot*Math.PI/180);
      ctx.imageSmoothingQuality='high';
      ctx.drawImage(layerSrc(im), -wPx/2, -hPx/2, wPx, hPx);
      ctx.restore();
    }
  }
  ctx.restore();
  // punch handle notches (real template shape): transparent bites at both short edges
  if(E.notch){
    const ppm = W / E.wrap.w;
    const {r, y1, y2} = notchGeom(E.wrap.w, E.wrap.h);
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();
    for(const [cxp,cyp] of [[0,y1*ppm],[W,y1*ppm],[0,y2*ppm],[W,y2*ppm]]){
      ctx.moveTo(cxp+r*ppm, cyp);          // moveTo avoids chained-arc fill artifacts
      ctx.arc(cxp, cyp, r*ppm, 0, Math.PI*2);
    }
    ctx.fill();
    ctx.restore();
  }
}
function rebuildTexture(){
  const W = 1400;
  const H = Math.round(W * state.wrap.h / state.wrap.w);
  tex.width=W; tex.height=H;
  drawArtwork(tex.getContext('2d'), W, H, W/state.wrap.w, false);
  const d = activeDesign(); if(d) d.ver = (d.ver||0)+1;   // invalidate caches
}

/* ---- flat artwork composition (moved R-3: raster lives with drawArtwork) ---- */
async function composeArtFlat(di, env){
  const E = env || state;
  const ppm = DPI/25.4;
  const W=Math.round(E.wrap.w*ppm), H=Math.round(E.wrap.h*ppm);
  const c=document.createElement('canvas'); c.width=W; c.height=H;
  drawArtwork(c.getContext('2d'), W, H, ppm, E.mirror,
              di===undefined ? E.activeDesign : di, E);
  // flatten onto white — notch bites print as unprinted white paper
  const f=document.createElement('canvas'); f.width=W; f.height=H;
  const fc=f.getContext('2d'); fc.fillStyle='#fff'; fc.fillRect(0,0,W,H); fc.drawImage(c,0,0);
  return f;
}
